{
  "name": "test_run",
  "description": "Run tests of a workspace. Fast by default on Maven projects: after one Maven prepare per workspace, only changed sources are compiled and the tests run in one JVM (seconds); mode=\"build\" runs the project's Maven/Gradle (the final check). files=[{path, content|edits}] writes before running, so a try is one call. Every result is kept per test, so workspace_patch can show which tests failed before the fix and pass after it (red-green). The answer has: each test, its status and time, failures with message and the code parts to work on (the repo frames of the stack trace with the lines around them), compile errors with their lines, and the output tail. With env + db (or ddl_path), the run gets a throwaway Postgres database loaded with the DDL snapshot, passed to Spring as SPRING_DATASOURCE_*. Shown as a view. Takes a while: if it answers \"running\", call it again with that job id.",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "workspace": {
        "type": "string",
        "description": "Workspace id"
      },
      "tests": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Test classes (FooTest) or Class#method"
      },
      "files": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "path": {
              "type": "string"
            },
            "content": {
              "type": "string"
            },
            "edits": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "find": {
                    "type": "string"
                  },
                  "replace": {
                    "type": "string"
                  }
                }
              }
            }
          },
          "required": [
            "path"
          ]
        },
        "description": "Write these first (like workspace_write), then run: one call per try"
      },
      "mode": {
        "type": "string",
        "enum": [
          "auto",
          "fast",
          "build"
        ],
        "default": "auto",
        "description": "fast: compile only what changed and run in one JVM (Maven projects; a few seconds); build: the project's Maven/Gradle (the final check before the patch); auto: fast where it fits"
      },
      "env": {
        "type": "string",
        "description": "With db: the environment of the DDL snapshot"
      },
      "db": {
        "type": "string",
        "description": "Database to snapshot into the throwaway test database"
      },
      "ddl_path": {
        "type": "string",
        "description": "Or: a DDL file in the workspace to load (e.g. src/test/resources/dt-schema/pay.sql)"
      },
      "fixture_path": {
        "type": "string",
        "description": "Saved src/test/resources/dt-fixtures/<name>; replay its PG databases on scratch Postgres and expose Kafka files as DT_FIXTURE_PATH"
      },
      "fixture_template": {
        "type": "boolean",
        "default": false,
        "description": "Reuse a verified immutable prefilled PostgreSQL template and allocate private leased clones"
      },
      "fixture_bindings": {
        "type": "object",
        "additionalProperties": {
          "type": "string"
        },
        "description": "For multiple databases: {orders:\"SPRING_DATASOURCE\",billing:\"BILLING_DATASOURCE\"}; each prefix gets _URL, _USERNAME, _PASSWORD"
      },
      "allow_incomplete": {
        "type": "boolean",
        "default": false,
        "description": "Replay a fixture with reported gaps (review fixture explorer first)"
      },
      "job": {
        "type": "string",
        "description": "A job id from an earlier \"running\" answer"
      },
      "check": {
        "type": "boolean",
        "default": true,
        "description": "Compile the written Java files right away"
      },
      "fix": {
        "type": "boolean",
        "default": true,
        "description": "Apply the clear compile fixes to the files (false: offer them as suggestions)"
      }
    },
    "required": [
      "workspace"
    ]
  }
}
